const fitFrame=(frame)=>{const host=frame.parentElement;const scale=host.clientWidth/1440;if(!scale)return;frame.style.transform=`scale(${scale})`;frame.style.height=`${Math.max(1100,host.clientHeight/scale)}px`};const previewFrames=document.querySelectorAll('.preview-viewport iframe');previewFrames.forEach(f=>{const o=new ResizeObserver(()=>fitFrame(f));o.observe(f.parentElement);fitFrame(f)});
